using System;
using System.Buffers;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Diagnostics.CodeAnalysis;
using System.IO;
using System.Runtime.CompilerServices;
using System.Threading.Tasks;
using AvroSharp.Generic;
using AvroSharp.IO;
using AvroSharp.Schemas;
using AvroSharp.Serialization;
using Confluent.Kafka;
using Confluent.SchemaRegistry;
using ConfluentSchema = Confluent.SchemaRegistry.Schema;

namespace AvroSharp.Confluent;

/// <summary>
/// Reads values in Confluent Schema Registry framing as a type generated by AvroSharp, a primitive, or generic values
/// (<see cref="AvroSharpGeneric"/>). The writer's schema comes from the registry by the message's schema ID (Confluent's
/// client caches it), and the data is resolved to the type's own schema, so data of older and newer versions reads.
/// It derives from Confluent's <see cref="AsyncDeserializer{T, TParsedSchema}"/>.
/// </summary>
/// <typeparam name="T">The type read.</typeparam>
/// <remarks>
/// It is both asynchronous and synchronous (<see cref="IDeserializer{T}"/>), which Confluent.Kafka's consumer calls.
/// Once a schema ID's reader is known, the synchronous path reads without a task. It waits for the registry the first
/// time, and on every message with <c>use.latest.version</c> or <c>use.latest.with.metadata</c>, or whose schema has
/// rules, which can run asynchronously.
/// </remarks>
public sealed class AvroSharpDeserializer<T> : AsyncDeserializer<T, AvroSchema>, IDeserializer<T>
{
    private readonly AvroTypeInfo<T> _type;
    private readonly bool _failOnTrailingData;
    private readonly bool _strict;

    // The writer schema and reader of each schema ID, once known, when reading it depends on nothing else (no latest
    // schema, and no rules): the synchronous path reads with them.
    private readonly ConcurrentDictionary<(int? Id, Guid? Guid), (AvroSchema Writer, AvroReadFunc<T> Read)> _known = new();

    // The writer schema of each subject and schema ID, and the pairs of writer schema ID and latest schema ID without
    // migrations between them, for the messages that can't take the path above.
    private readonly ConcurrentDictionary<(string? Subject, int? Id, Guid? Guid), (ConfluentSchema Json, AvroSchema Parsed)> _writers = new();
    private readonly ConcurrentDictionary<(int? Id, Guid? Guid, int Latest), IList<Migration>> _migrations = new();

    // The reader of each writer schema. Confluent's client caches a parsed schema per ID, so the instance is the key.
    private readonly ConditionalWeakTable<AvroSchema, AvroReadFunc<T>> _readers = new();
    private readonly ConditionalWeakTable<AvroSchema, AvroReadFunc<T>>.CreateValueCallback _createReader;

    // For generic values without a reader schema: the reader of each writer schema resolved to each latest schema.
    private readonly ConditionalWeakTable<AvroSchema, ConditionalWeakTable<AvroSchema, AvroReadFunc<T>>> _latestReaders = new();

    /// <summary>
    /// Creates a deserializer of a generated type or a primitive, which <see cref="AvroTypes"/> knows. On .NET Standard,
    /// pass the type's <c>AvroTypeInfo</c> to the other constructor, or register it first.
    /// </summary>
    /// <param name="client">The schema registry.</param>
    /// <param name="config">The settings, or <see langword="null"/> for the defaults.</param>
    /// <param name="ruleRegistry">The data contract rules, or <see langword="null"/> for <see cref="RuleRegistry.GlobalInstance"/>.</param>
    /// <exception cref="ArgumentException"><paramref name="config"/> has a key the deserializer doesn't know, or sets <see cref="TombstoneBehavior.Strict"/> for a value type.</exception>
    /// <exception cref="InvalidOperationException"><typeparamref name="T"/> is not registered in <see cref="AvroTypes"/> (Confluent.Kafka's <c>Null</c> needn't be: its schema is <c>"null"</c>).</exception>
    public AvroSharpDeserializer(ISchemaRegistryClient client, AvroSharpDeserializerConfig? config = null, RuleRegistry? ruleRegistry = null)
        : this(client, ConfluentTypes.Get<T>(), config, ruleRegistry)
    {
    }

    /// <summary>Creates a deserializer of the type that <paramref name="type"/> reads and writes.</summary>
    /// <param name="client">The schema registry.</param>
    /// <param name="type">The type's schema and serializers.</param>
    /// <param name="config">The settings, or <see langword="null"/> for the defaults.</param>
    /// <param name="ruleRegistry">The data contract rules, or <see langword="null"/> for <see cref="RuleRegistry.GlobalInstance"/>.</param>
    /// <exception cref="ArgumentException"><paramref name="config"/> has a key the deserializer doesn't know, or sets <see cref="TombstoneBehavior.Strict"/> for a value type.</exception>
    public AvroSharpDeserializer(ISchemaRegistryClient client, AvroTypeInfo<T> type, AvroSharpDeserializerConfig? config = null, RuleRegistry? ruleRegistry = null)
        : base(client, config, ruleRegistry ?? RuleRegistry.GlobalInstance)
    {
        ArgumentNullException.ThrowIfNull(client);
        ArgumentNullException.ThrowIfNull(type);
        _type = type;
        _createReader = schema =>
        {
            if (_strict)
            {
                Tombstones.CheckSchema(schema, "AvroSharpDeserializer");
            }

            return _type.ReadFor(schema);
        };
        subjectNameStrategy = (config?.SubjectNameStrategy ?? SubjectNameStrategy.Associated).ToAsyncDelegate(client, config);
        if (config is null)
        {
            return;
        }

        ConfigKeys.Check(config, ConfigKeys.Deserializer, "AvroSharpDeserializer");
        useLatestVersion = config.UseLatestVersion ?? useLatestVersion;
        useLatestWithMetadata = config.UseLatestWithMetadata ?? useLatestWithMetadata;
        _failOnTrailingData = config.FailOnTrailingData ?? false;
        if (config.TombstoneBehavior == TombstoneBehavior.Strict)
        {
            // The schemas are checked as they are met: each writer's schema (and the latest), which can differ.
            if (!Tombstones.CanHoldNull<T>())
            {
                throw new ArgumentException(Tombstones.TypeMessage<T>("AvroSharpDeserializer"), nameof(config));
            }

            _strict = true;
        }

        if (config.SchemaIdStrategy is { } strategy)
        {
            schemaIdDecoder = strategy.ToDeserializer();
        }
    }

    /// <summary>Reads a value: the writer's schema by the message's schema ID, then the data resolved to the type's schema.</summary>
    /// <param name="data">The message body.</param>
    /// <param name="isNull">Whether the message has no body; the result is then the default of <typeparamref name="T"/>.</param>
    /// <param name="context">The topic, the component (key or value) and the headers.</param>
    [SuppressMessage("Design", "CA1031:Do not catch general exception types", Justification = "Every exception goes into the returned task, as an async method's does.")]
    public override Task<T> DeserializeAsync(ReadOnlyMemory<byte> data, bool isNull, SerializationContext context)
    {
        var start = Telemetry.Measuring ? Telemetry.Timestamp() : 0;
        try
        {
            if (isNull)
            {
                return Task.FromResult(Tombstone(context));
            }

            // Once the schema ID's reader is known, the message is read without the async state machine.
            var id = new SchemaId(SchemaType.Avro);
            var payload = schemaIdDecoder.Decode(data, context, ref id);
            if (_known.TryGetValue((id.Id, id.Guid), out var known))
            {
                var value = Read(known.Read, known.Writer, payload);
                if (start != 0)
                {
                    Telemetry.Record(SerdeName, context, start, null);
                }

                return Task.FromResult(value);
            }

            var task = DeserializeSlowAsync(payload, id, context);
            return start == 0 ? task : Telemetry.ObserveAsync(task, SerdeName, context, start);
        }
        catch (Exception e)
        {
            if (start != 0)
            {
                Telemetry.Record(SerdeName, context, start, e);
            }

            return Task.FromException<T>(e);
        }
    }

    // A message whose schema ID's reader isn't known yet, or whose reading depends on the latest schema or on rules.
    private async Task<T> DeserializeSlowAsync(ReadOnlyMemory<byte> payload, SchemaId id, SerializationContext context)
    {
        var isKey = context.Component == MessageComponentType.Key;
        var subject = await GetSubjectName(context.Topic, isKey, null).ConfigureAwait(false);
        var (writerJson, writerSchema) = await WriterSchemaAsync(subject, id).ConfigureAwait(false);
        subject ??= await GetSubjectName(context.Topic, isKey, (writerSchema as RecordSchema)?.FullName).ConfigureAwait(false);
        var latest = subject is null ? null : await GetReaderSchema(subject).ConfigureAwait(false);

        if (writerJson.RuleSet?.EncodingRules is { Count: > 0 })
        {
            var decoded = await ExecuteRules(isKey, subject, context.Topic, context.Headers, RulePhase.Encoding, RuleMode.Read, null, writerJson, payload, null).ConfigureAwait(false);
            payload = decoded is byte[] bytes ? bytes : (ReadOnlyMemory<byte>)decoded!;
        }

        if (latest is not null && await MigrationsAsync(subject!, writerJson, latest, id).ConfigureAwait(false) is { Count: > 0 } migrations)
        {
            // From here on the message is the latest schema's: the value the migration rules made, encoded in it.
            var latestSchema = await GetParsedSchema(latest).ConfigureAwait(false);
            payload = await MigrateAsync(migrations, isKey, subject!, context, writerSchema, latestSchema, payload).ConfigureAwait(false);
            (writerJson, writerSchema) = (latest, latestSchema);
        }

        var read = ReadAsLatest is not null && latest is not null
            ? LatestReader(writerSchema, await GetParsedSchema(latest).ConfigureAwait(false))
            : _readers.GetValue(writerSchema, _createReader);
        var value = Read(read, writerSchema, payload);
        var target = (ConfluentSchema?)latest ?? writerJson;
        if (target.RuleSet?.DomainRules is { Count: > 0 })
        {
            if (ApacheAvroGeneric.HasCelRules(target.RuleSet) && !RegistrySchemas.IsRawBytes(writerSchema) && ApacheAvroGeneric.IsAvailable)
            {
                // CEL reads a value by its Avro field names only as Apache.Avro's generic model: the rules see the data
                // decoded that way, in the rules' schema. A rule that returns another value (a transform) is read back.
                var targetSchema = latest is null ? writerSchema : await GetParsedSchema(latest).ConfigureAwait(false);
                var generic = ApacheAvroGeneric.Decode(writerSchema, targetSchema, payload);
                var result = await ExecuteRules(isKey, subject, context.Topic, context.Headers, RuleMode.Read, null, target, generic, RuleSupport.NoFieldTransformsAsync).ConfigureAwait(false);
                if (!ReferenceEquals(result, generic) || ApacheAvroGeneric.HasTransforms(target.RuleSet))
                {
                    value = Read(_readers.GetValue(targetSchema, _createReader), targetSchema, ApacheAvroGeneric.Encode(targetSchema, result));
                }
            }
            else
            {
                value = (T)(await ExecuteRules(isKey, subject, context.Topic, context.Headers, RuleMode.Read, null, target, value, RuleSupport.NoFieldTransformsAsync).ConfigureAwait(false))!;
            }
        }
        else if (latest is null && !useLatestVersion && useLatestWithMetadata is null && writerJson.RuleSet?.EncodingRules is not { Count: > 0 })
        {
            _known.TryAdd((id.Id, id.Guid), (writerSchema, read));
        }

        return value;
    }

    /// <summary>
    /// Reads a value without a task once its schema ID's reader is known; until then, and with settings or rules that
    /// can run asynchronously, it waits for <see cref="DeserializeAsync"/>.
    /// </summary>
    /// <param name="data">The message body.</param>
    /// <param name="isNull">Whether the message has no body; the result is then the default of <typeparamref name="T"/>.</param>
    /// <param name="context">The topic, the component (key or value) and the headers.</param>
    [SuppressMessage("Usage", "VSTHRD002:Avoid problematic synchronous waits", Justification = "Confluent.Kafka's consumer calls deserializers synchronously: it waits only until the schema ID's reader is known, or with settings or rules that can run asynchronously.")]
    public T Deserialize(ReadOnlySpan<byte> data, bool isNull, SerializationContext context)
    {
        var start = Telemetry.Measuring ? Telemetry.Timestamp() : 0;
        try
        {
            if (isNull)
            {
                return Tombstone(context);
            }

            var message = data.ToArray();
            var id = new SchemaId(SchemaType.Avro);
            var payload = schemaIdDecoder.Decode(message, context, ref id);
            var value = _known.TryGetValue((id.Id, id.Guid), out var known)
                ? Read(known.Read, known.Writer, payload)
                : DeserializeSlowAsync(payload, id, context).GetAwaiter().GetResult();
            if (start != 0)
            {
                Telemetry.Record(SerdeName, context, start, null);
            }

            return value;
        }
        catch (Exception e) when (start != 0 && Recorded(e, context, start))
        {
            throw;
        }
    }

    private const string SerdeName = "deserializer";

    // Records a failure in an exception filter, which then lets the exception go on unchanged.
    private static bool Recorded(Exception e, SerializationContext context, long start)
    {
        Telemetry.Record(SerdeName, context, start, e);
        return false;
    }

    // The migration rules between the writer's schema and the latest, looked up once per writer schema and latest
    // schema: Confluent's lookup fetches the writer's version, and every version in between, from the registry.
    private async Task<IList<Migration>> MigrationsAsync(string subject, ConfluentSchema writerJson, RegisteredSchema latest, SchemaId id)
    {
        var key = (id.Id, id.Guid, latest.Id);
        if (_migrations.TryGetValue(key, out var known))
        {
            return known;
        }

        IList<Migration> migrations;
        using (Telemetry.RegistryCall("migrations", subject))
        {
            migrations = await GetMigrations(subject, writerJson, latest).ConfigureAwait(false);
        }

        _migrations.TryAdd(key, migrations);
        return migrations;
    }

    // Runs migration rules (UPGRADE or DOWNGRADE, such as JSONata) as Confluent's and Java's deserializers do: on the
    // value as Avro JSON, read with the writer's schema; the JSON they return is a value of the latest schema, which is
    // encoded for the read that follows.
    private async Task<ReadOnlyMemory<byte>> MigrateAsync(IList<Migration> migrations, bool isKey, string subject, SerializationContext context, AvroSchema writerSchema, AvroSchema latestSchema, ReadOnlyMemory<byte> payload)
    {
        if (RegistrySchemas.IsRawBytes(writerSchema) || RegistrySchemas.IsRawBytes(latestSchema))
        {
            throw new NotSupportedException($"The subject '{subject}' has migration rules for a top-level \"bytes\" schema, which AvroSharp.Confluent doesn't run.");
        }

        var value = GenericDatumReader.Create(writerSchema).Read(payload.Span);
        var json = MigrationJson.Parse(GenericDatumJsonWriter.Create(writerSchema).WriteToString(value));
        var migrated = await ExecuteMigrations(migrations, isKey, subject, context.Topic, context.Headers, json).ConfigureAwait(false);
        var latest = GenericDatumJsonReader.Create(latestSchema).Read(MigrationJson.ToJson(migrated));
        var encoded = new ArrayBufferWriter<byte>(payload.Length + 16);
        GenericDatumWriter.Create(latestSchema).Write(encoded, latest);
        return encoded.WrittenMemory;
    }

    // The writer's schema, as registered and parsed, by its ID: fetched once, rather than looked up through Confluent's
    // caches on every message, which hash the whole schema text.
    private async Task<(ConfluentSchema Json, AvroSchema Parsed)> WriterSchemaAsync(string? subject, SchemaId id)
    {
        var key = (subject, id.Id, id.Guid);
        if (_writers.TryGetValue(key, out var known))
        {
            return known;
        }

        using var activity = Telemetry.RegistryCall("get_schema", subject);
        var writer = await GetWriterSchema(subject, id).ConfigureAwait(false);
        _writers.TryAdd(key, writer);
        return writer;
    }

    /// <summary>
    /// Gets or sets how subjects are named, as a function (by default, the one of the configuration's
    /// <c>subject.name.strategy</c>), for names that <see cref="global::Confluent.SchemaRegistry.SubjectNameStrategy"/>
    /// can't express, such as a schema context (<c>:.context:orders-value</c>) or a team's prefix. It replaces the
    /// configuration's <c>subject.name.strategy</c>. It is asked when a topic's schema is first read, and on every message
    /// whose settings need the subject (<c>use.latest.version</c> and the others), so it should give the same subject
    /// for the same topic and component.
    /// </summary>
    /// <example><c>new AvroSharpDeserializer&lt;Order&gt;(registry) { CustomSubjectNameStrategy = (context, recordType) =&gt; Task.FromResult("billing." + context.Topic) }</c></example>
    public AsyncSubjectNameStrategyDelegate CustomSubjectNameStrategy
    {
        get => subjectNameStrategy;
        init => subjectNameStrategy = value ?? throw new ArgumentNullException(nameof(value));
    }

    /// <inheritdoc/>
    protected override Task<AvroSchema> ParseSchema(ConfluentSchema schema) => RegistrySchemas.ParseAsync(schema, ResolveReferences);

    // A tombstone. A value type can't be null (a generic value can: AvroValue's default is null), as in Confluent's
    // deserializer. With TombstoneBehavior.Strict a key has no tombstone.
    private T Tombstone(SerializationContext context)
    {
        if (_strict && context.Component == MessageComponentType.Key)
        {
            throw Tombstones.NullKey("AvroSharpDeserializer");
        }

        return default(T) is null || typeof(T) == typeof(AvroValue)
            ? default!
            : throw new InvalidOperationException($"The message has no body (a tombstone), which can't be read as the value type {typeof(T).Name}.");
    }

    /// <summary>
    /// Gets or sets how values are read when the subject has a latest schema (<c>use.latest.version</c> or
    /// <c>use.latest.with.metadata</c>): resolved from the writer's schema to it, as Confluent's generic deserializer
    /// reads. <see langword="null"/> reads them as the type's schema, as for generated types.
    /// </summary>
    internal Func<AvroSchema, AvroSchema, AvroReadFunc<T>>? ReadAsLatest { get; init; }

    private AvroReadFunc<T> LatestReader(AvroSchema writerSchema, AvroSchema latestSchema) =>
        _latestReaders.GetOrCreateValue(writerSchema).GetValue(latestSchema, latest =>
        {
            if (_strict)
            {
                Tombstones.CheckSchema(writerSchema, "AvroSharpDeserializer");
                Tombstones.CheckSchema(latest, "AvroSharpDeserializer");
            }

            return ReadAsLatest!(writerSchema, latest);
        });

    private T Read(AvroReadFunc<T> read, AvroSchema writerSchema, ReadOnlyMemory<byte> payload)
    {
        if (RegistrySchemas.IsRawBytes(writerSchema))
        {
            // A value of the schema "bytes" is the message body alone, without Avro's length prefix, as Confluent's
            // serdes (.NET and Java) write it. The two types that read it as written take the body directly; any other
            // reads it through Avro's encoding, with the prefix added.
            if (typeof(T) == typeof(byte[]))
            {
                return (T)(object)payload.ToArray();
            }

            if (typeof(T) == typeof(AvroValue))
            {
                return (T)(object)AvroValue.FromBytes(payload.ToArray());
            }

            var encoded = new ArrayBufferWriter<byte>(payload.Length + 10);
            var writer = new AvroWriter(encoded);
            writer.WriteBytes(payload.Span);
            writer.Flush();
            var bytesReader = new AvroReader(encoded.WrittenSpan);
            return read(ref bytesReader);
        }

        var reader = new AvroReader(payload.Span);
        var value = read(ref reader);
        if (_failOnTrailingData && reader.BytesConsumed != payload.Length)
        {
            throw new InvalidDataException(
                $"The message has {payload.Length - reader.BytesConsumed} bytes after the value, of {payload.Length}: a sign of a wrong " +
                "schema or a corrupt message (avro.deserializer.fail.on.trailing.data).");
        }

        return value;
    }
}
